#include "value.h"

/* PNG */
static const wxString s_value_16_png = wxT("");

wxIcon ibValue::GetIcon() const
{
	return GetIconGroup();
}

#include "backend/backend_picture.h"

wxIcon ibValue::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_value_16_png, wxSize(16, 16));

	return icon;
}